('b7191e58-bcca-572b-ae4e-40518fa9c2ae'::uuid,'LOG-F03','Resource inventory and commitment entry','Chapter 6 LOG-F03 (SOPs 6-06 and 6-12). One item or commitment per entry; blank means not reported.','d61fc0e9-7136-5375-ab68-40132bc8dd3c'::uuid,'{"fields": [{"key": "holder", "label": "Holder", "type": "select", "required": true, "options": ["City office", "Barangay (BDRRMC)", "Partner (agreement)", "Supplier (framework agreement)"]}, {"key": "item", "label": "Item, team or service", "type": "text", "required": true}, {"key": "quantity", "label": "Quantity", "type": "integer", "required": true, "min": 0}, {"key": "serviceable", "label": "Serviceable", "type": "select", "required": true, "options": ["Serviceable", "Needs repair", "Unserviceable", "Not checked"]}, {"key": "location", "label": "Location or barangay", "type": "text", "required": true}, {"key": "agreement_ref", "label": "Agreement reference (partner or supplier)", "type": "text", "required": false, "hint": "Required for partner and supplier entries"}, {"key": "activation_trigger", "label": "Activation trigger", "type": "text", "required": false}, {"key": "contact_position", "label": "Contact (position)", "type": "text", "required": true, "hint": "Position, not a personal name"}, {"key": "last_confirmed", "label": "Last confirmed or tested", "type": "date", "required": true}]}'::jsonb,'draft',1),
('beee6ad0-4e36-5883-8ed8-f95a6ecd3ea6'::uuid,'ME-F01','LDRRMP M&E matrix entry','Chapter 7 ME-F01 (SOP 7-01; Annex 7-B), aligned with Form 5D of the 10-Year Plan. One row per indicator.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "indicator_code", "label": "Code", "type": "text", "required": true}, {"key": "result_level", "label": "Result level", "type": "select", "required": true, "options": ["Impact", "Outcome", "Output", "Input and process"]}, {"key": "definition", "label": "Indicator and definition", "type": "textarea", "required": true, "hint": "What is counted, how, and what is excluded"}, {"key": "unit", "label": "Unit and disaggregation", "type": "text", "required": true, "hint": "Sex, age, disability and barangay where relevant"}, {"key": "baseline", "label": "Baseline (value, year, source)", "type": "text", "required": true, "hint": "Or the dated plan to establish one"}, {"key": "targets", "label": "Targets by year to 2032", "type": "textarea", "required": true}, {"key": "source_method", "label": "Data source and method", "type": "text", "required": true}, {"key": "frequency", "label": "Frequency", "type": "select", "required": true, "options": ["Quarterly", "Annual", "Per event"]}, {"key": "responsible_office", "label": "Responsible office", "type": "text", "required": true}, {"key": "framework_codes", "label": "Framework codes", "type": "text", "required": false, "hint": "Ten Essentials; NDRRMP outcome; DILG pillar; Sendai target; IAT indicator"}, {"key": "current_status", "label": "Current value and status", "type": "select", "required": false, "options": ["On track", "Off track", "Not reported"]}]}'::jsonb,'draft',1),
('41003415-6b0f-5b98-a74f-e0db5f1cc434'::uuid,'ME-F02','Annual LDRRMP progress and results report','Chapter 7 ME-F02 (SOP 7-01). Each January for the previous year; to the CDRRMC and the LDC.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "year", "label": "Year reported", "type": "integer", "required": true, "min": 2023}, {"key": "indicators_reported", "label": "Indicators with a value", "type": "integer", "required": true, "min": 0}, {"key": "indicators_total", "label": "Indicators in the matrix", "type": "integer", "required": true, "min": 0}, {"key": "summary", "label": "Results against targets", "type": "textarea", "required": true}, {"key": "ppa_status", "label": "PPA status", "type": "textarea", "required": false}, {"key": "consistency_note", "label": "AIP consistency note", "type": "textarea", "required": false, "hint": "NDRRMC Memo No. 147, s. 2017"}, {"key": "capa_refs", "label": "Gaps sent to the CAPA register", "type": "text", "required": false}, {"key": "cdrrmc_resolution", "label": "CDRRMC resolution approving the report", "type": "text", "required": false}]}'::jsonb,'draft',1),
('6045195e-b296-504b-bb84-eaa1e6a6e63c'::uuid,'ME-F03','After-action review report','Chapter 7 ME-F03 (SOP 7-04), full or focused form. Receives ER-F06 from Chapter 4, SOP 4-09.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "form_type", "label": "Form", "type": "select", "required": true, "options": ["Full AAR", "Focused AAR (near miss or procedural failure)"]}, {"key": "event", "label": "Event and dates", "type": "text", "required": true}, {"key": "facilitator", "label": "Facilitator (position; held no command role)", "type": "text", "required": true}, {"key": "timeline_sources", "label": "Timeline sources", "type": "textarea", "required": true, "hint": "Warning product IDs, logbook, SitReps, ER-F06, resource requests"}, {"key": "expected_vs_actual", "label": "What was expected and what happened", "type": "textarea", "required": true}, {"key": "findings", "label": "Findings with evidence and causes", "type": "textarea", "required": true}, {"key": "keep_change", "label": "What to keep and what to change", "type": "textarea", "required": true}, {"key": "capa_entries", "label": "CAPA entries opened (ME-F05)", "type": "text", "required": false}]}'::jsonb,'draft',1),
('929407d4-f96e-5c01-b553-e28328a76b14'::uuid,'ME-F04','Exercise evaluation report','Chapter 7 ME-F04 (SOP 7-04), full or short form. Within 15 days of a functional or full-scale exercise; 7 days of a tabletop or drill.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "form_type", "label": "Form", "type": "select", "required": true, "options": ["Full (functional or full-scale exercise)", "Short (tabletop or drill)"]}, {"key": "exercise", "label": "Exercise, scenario and date", "type": "text", "required": true}, {"key": "objectives", "label": "Objectives tested", "type": "textarea", "required": true}, {"key": "participants", "label": "Participating offices and partners", "type": "textarea", "required": false}, {"key": "met", "label": "Objectives met", "type": "select", "required": true, "options": ["All", "Partly", "None"]}, {"key": "findings", "label": "Findings with evidence", "type": "textarea", "required": true}, {"key": "capa_entries", "label": "CAPA entries opened (ME-F05)", "type": "text", "required": false}]}'::jsonb,'draft',1),
('1ad2a8ef-dfb0-592f-9112-ad8aa20adf35'::uuid,'ME-F05','Corrective and preventive action (CAPA) register entry','Chapter 7 ME-F05 (SOPs 7-03 to 7-09). Root cause, verification and effectiveness review per Ch.1 Table 1.23.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "source", "label": "Source", "type": "select", "required": true, "options": ["AAR", "Exercise", "IAT", "Validation", "COA observation", "Data breach", "Lesson", "Other"]}, {"key": "problem", "label": "Problem statement and risk consequence", "type": "textarea", "required": true}, {"key": "priority", "label": "Priority", "type": "select", "required": true, "options": ["High", "Medium", "Low"]}, {"key": "root_cause", "label": "Root cause", "type": "textarea", "required": false}, {"key": "action", "label": "Action", "type": "textarea", "required": true}, {"key": "responsible", "label": "Responsible office", "type": "text", "required": true}, {"key": "target_date", "label": "Target date", "type": "date", "required": true}, {"key": "loop", "label": "Type of learning", "type": "select", "required": false, "options": ["Single-loop (fix the instance)", "Double-loop (change the rule, plan or design)"]}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Open", "Planned", "In progress", "Implemented", "Closed – effective", "Reopened"]}, {"key": "effectiveness_evidence", "label": "Effectiveness evidence", "type": "textarea", "required": false, "hint": "Evidence, not assertion; the CDRRMC closes High items"}]}'::jsonb,'draft',1),
('ea2002fc-bb48-54cb-9279-6f7c8ae1f4aa'::uuid,'ME-F06','Reporting calendar and compliance tracker entry','Chapter 7 ME-F06 (sec. 10; SOP 7-06). Confirmed each January with the issuing agency.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "report", "label": "Report", "type": "text", "required": true}, {"key": "recipient", "label": "Recipient body", "type": "text", "required": true}, {"key": "basis", "label": "Legal or policy basis", "type": "text", "required": false}, {"key": "due", "label": "Due date", "type": "date", "required": true}, {"key": "submitted", "label": "Submitted on", "type": "date", "required": false}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Not due", "Submitted on time", "Submitted late", "Missed"]}]}'::jsonb,'draft',1),
('2f83bb04-7e96-592c-8096-4d272f194c4b'::uuid,'ME-F07','Disaster event and loss record','Chapter 7 ME-F07 (SOP 7-07; Annex 7-E). Aggregates only; every figure carries its source (RA 10173).','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "event", "label": "Event name and hazard", "type": "text", "required": true}, {"key": "hazard", "label": "Hazard", "type": "select", "required": true, "options": ["Tropical cyclone", "Storm surge", "Riverine flood", "Flash flood", "Rain-induced landslide", "Drought (El Nino)", "Extreme heat", "Earthquake", "Tsunami", "Industrial / geothermal incident", "Disease outbreak", "Other"]}, {"key": "start_date", "label": "Start date", "type": "date", "required": true}, {"key": "barangays_affected", "label": "Barangays affected", "type": "integer", "required": false, "min": 0, "max": 85}, {"key": "deaths", "label": "Deaths", "type": "integer", "required": false, "min": 0}, {"key": "missing", "label": "Missing", "type": "integer", "required": false, "min": 0}, {"key": "injured", "label": "Injured", "type": "integer", "required": false, "min": 0}, {"key": "families_affected", "label": "Families affected", "type": "integer", "required": false, "min": 0}, {"key": "persons_affected", "label": "Persons affected", "type": "integer", "required": false, "min": 0}, {"key": "damage_php", "label": "Damage (PHP)", "type": "number", "required": false, "min": 0}, {"key": "sources", "label": "Sources of the figures", "type": "textarea", "required": true, "hint": "Final SitRep, DROMIC, RDANA, PDNA"}, {"key": "version_note", "label": "Version and what changed", "type": "text", "required": false}]}'::jsonb,'draft',1),
('59808c80-75c4-5bc8-a2b9-e2672dc94aaf'::uuid,'ME-F08','Lessons and peer-learning register entry','Chapter 7 ME-F08 (SOP 7-08). Without a proposed change it is an observation, not yet a lesson.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "source", "label": "Source", "type": "select", "required": true, "options": ["AAR", "Exercise", "IAT", "Peer exchange", "Network event", "Other"]}, {"key": "lesson", "label": "Lesson", "type": "textarea", "required": true}, {"key": "change", "label": "Change proposed", "type": "textarea", "required": true}, {"key": "change_type", "label": "What changes", "type": "multiselect", "required": true, "options": ["Plan", "Form", "Procedure (Manual)", "Training", "MODE rule", "Other"]}, {"key": "decision", "label": "CDRRMO Head decision", "type": "select", "required": false, "options": ["Adopt", "Refer to the CDRRMC or the Mayor", "Not adopted"]}, {"key": "capa_ref", "label": "CAPA entry (ME-F05)", "type": "text", "required": false}]}'::jsonb,'draft',1),
('63574fd3-00af-5e5f-b21f-7c1b162e9b66'::uuid,'ME-F09','DRRM data inventory, sharing register and breach log','Chapter 7 ME-F09 (SOP 7-09), parts A to C. The DPO reviews; NPC notice within 72 hours of knowledge of a breach.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'{"fields": [{"key": "part", "label": "Part", "type": "select", "required": true, "options": ["A. Data inventory", "B. Data-sharing register", "C. Breach log"]}, {"key": "item", "label": "Form, system or dataset", "type": "text", "required": true}, {"key": "purpose", "label": "Purpose", "type": "text", "required": true}, {"key": "office", "label": "Office", "type": "text", "required": true}, {"key": "personal_data", "label": "Holds personal data", "type": "checkbox", "required": false}, {"key": "retention", "label": "Retention period", "type": "text", "required": false}, {"key": "agreement_ref", "label": "Data-sharing agreement (part B)", "type": "text", "required": false}, {"key": "breach_known_at", "label": "Breach known at (part C)", "type": "datetime", "required": false}, {"key": "npc_notified_at", "label": "NPC notified at (part C)", "type": "datetime", "required": false}, {"key": "dpo_review", "label": "DPO reviewed", "type": "checkbox", "required": false}]}'::jsonb,'draft',1),
('9b3378b1-7fb6-56d0-a729-74d004cccd72'::uuid,'PTN-F01','Partner register entry','Chapter 8 PTN-F01 (SOPs 8-01, 8-02, 8-07, 8-08). Reviewed every year at the partner forum.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'{"fields": [{"key": "partner", "label": "Organisation", "type": "text", "required": true}, {"key": "partner_type", "label": "Type", "type": "select", "required": true, "options": ["National agency", "Province or other LGU", "Civil society organisation", "Private sector", "Academe", "Faith-based group", "Utility", "International organisation", "Other"]}, {"key": "agreement", "label": "Agreement", "type": "select", "required": true, "options": ["MOA or MOU", "Mutual aid agreement", "Framework agreement", "Coordination only"]}, {"key": "agreement_ref", "label": "Agreement reference and authority", "type": "text", "required": false, "hint": "SP resolution; signing date"}, {"key": "roles", "label": "Roles before, during and after events", "type": "textarea", "required": true}, {"key": "resources", "label": "Resources committed (also on LOG-F03)", "type": "textarea", "required": false}, {"key": "activation_trigger", "label": "Activation trigger", "type": "text", "required": false}, {"key": "contact_position", "label": "Contact (position)", "type": "text", "required": true}, {"key": "review_date", "label": "Next review", "type": "date", "required": true}]}'::jsonb,'draft',1),
