('5bae011b-2280-5899-b554-9539bfb53ced'::uuid,'PTN-F03','Mutual aid or augmentation request and status','Chapter 8 PTN-F03 (SOPs 8-02, 8-03, 8-08), inbound and outbound. Specific enough to act on.','cb5fb5fd-5044-57b7-84fe-dff921b0c759'::uuid,'{"fields": [{"key": "direction", "label": "Direction", "type": "select", "required": true, "options": ["Outbound request (City asks)", "Inbound request (City is asked)", "Assistance sent to another LGU"]}, {"key": "route", "label": "Route", "type": "select", "required": true, "options": ["Mutual aid agreement", "Province (PDRRMO)", "OCD VIII / national agency", "Other LGU"]}, {"key": "resource", "label": "Resource and quantity", "type": "textarea", "required": true}, {"key": "location", "label": "Where needed", "type": "text", "required": true}, {"key": "needed_by", "label": "Needed by", "type": "datetime", "required": true}, {"key": "committed", "label": "City resources already committed", "type": "textarea", "required": false}, {"key": "approved_by", "label": "Approved by (position)", "type": "text", "required": true}, {"key": "sent_at", "label": "Sent at", "type": "datetime", "required": false}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Sent", "Acknowledged", "In transit", "Delivered", "Declined", "Demobilised"]}]}'::jsonb,'draft',1),
